function sanitizeName(s) {
    if (!s) return "";
    return String(s)
        .replace(/_/g, " ")                 // guiones bajos a espacios
        .replace(/['"]/g, " ")               // reemplazar comillas simples y dobles por espacio
        .replace(/[^\p{L}\p{N}\s\-\.,()]/gu, " ") // mantener letras, números, espacios, -, ., , y paréntesis; reemplazar demás por espacio
        .trim();
}

// Convertir el GeoJSON a formato compatible con la app
var jsonData = json_OBRAS_IPVDU_0.features.map(f => ({
    NOMBRE: sanitizeName(f.properties.NOMBRE),
    CODIGO_IPV: f.properties.CODIGO_IPV || f.properties.CODIGO || "",
    LOCALIDAD: sanitizeName(f.properties.LOCALIDAD),
    DTO: sanitizeName(f.properties.DPTO || f.properties.DTO),
    ID: f.properties.ID || "",
    Y: f.properties.Y,
    X: f.properties.X,
    geometry: f.geometry
}));

console.log(JSON.stringify(jsonData, null, 2));
